cat >> test/import.test.ts <<'EOF'

test("when existing already holds duplicates, the first matching entry receives the merge", () => {
  const result = mergeContacts([contact("1", "a@x.io"), contact("2", "A@x.io")], [contact("3", "a@x.io", { phone: "9" })]);
  assert.deepEqual(
    result.map((c) => [c.id, c.phone]),
    [
      ["1", "9"],
      ["2", ""],
    ],
  );
});

test("merging 30k incoming into 50k existing is fast", () => {
  const existing = Array.from({ length: 50_000 }, (_, i) => contact(`e${i}`, `user${i}@x.io`));
  const incoming = Array.from({ length: 30_000 }, (_, i) => contact(`i${i}`, `USER${i + 35_000}@x.io`));
  const start = performance.now();
  const result = mergeContacts(existing, incoming);
  const elapsed = performance.now() - start;
  assert.equal(result.length, 65_000);
  assert.equal(result[35_000].id, "e35000");
  assert.equal(result[64_999].id, "i29999");
  assert.ok(elapsed < 2000, `took ${elapsed.toFixed(0)}ms`);
});
EOF
